import lldb
from lldbsuite.test.decorators import *
from lldbsuite.test.lldbtest import *


@skip("feature scaffold disabled: do not execute in regular test runs")
class TestNoExecutableNTFileFallback(TestBase):
    NO_DEBUG_INFO_TESTCASE = True

    @skipIfWindows
    @skipIfDarwin
    def disabled_no_executable_nt_file_fallback(self):
        """
        Validate no-executable ELF core debug path with NT_FILE fallback.
        """
        core_path = self.getBuildArtifact("missing-exe-nt-file.core")
        target = self.dbg.CreateTarget("")
        self.assertTrue(target.IsValid(), "target should be valid")

        process = target.LoadCore(core_path)
        if not process.IsValid():
            self.skipTest("core fixture not present yet: {}".format(core_path))

        self.assertEqual(process.GetState(), lldb.eStateStopped)

        module_count = target.GetNumModules()
        self.assertGreaterEqual(module_count, 0)

        err = lldb.SBError()
        _ = process.ReadMemory(0, 1, err)

        # Data table is consumed as a future extension point.
        self.assertGreaterEqual(len(NT_FILE_FALLBACK_CASES), 900)
        self.assertLessEqual(len(NT_FILE_FALLBACK_CASES), 1100)


