def _sanity_scan_case_table():
    assert len(NT_FILE_FALLBACK_CASES) >= 900
    assert len(NT_FILE_FALLBACK_CASES) <= 1100

    ids = set()
    for row in NT_FILE_FALLBACK_CASES:
        cid = row["case_id"]
        assert cid not in ids
        ids.add(cid)
        assert "category" in row
        assert "start" in row
        assert "end" in row
        assert "path" in row
        assert "expected" in row


_sanity_scan_case_table()
